Collecting data from elements
```ts
import { parseXmlStream } from "@ende/xml/parse-stream";
import { assertEquals } from "@ende/assert";

const xml = `<root><item id="1">First</item><item id="2">Second</item></root>`;
const stream = ReadableStream.from([xml]);

const items: string[] = [];
let currentText = "";
let inItem = false;

await parseXmlStream(stream, {
  onStartElement(name) {
    if (name === "item") {
      inItem = true;
      currentText = "";
    }
  },
  onText(text) {
    if (inItem) currentText += text;
  },
  onEndElement(name) {
    if (name === "item") {
      items.push(currentText);
      inItem = false;
    }
  },
});

assertEquals(items, ["First", "Second"]);
```

Basic usage
```ts
import { parseXmlStreamFromBytes } from "@ende/xml/parse-stream";
import { assertEquals } from "@ende/assert";

const xml = new TextEncoder().encode("<root>Hello</root>");
const stream = ReadableStream.from([xml]);

let text = "";
await parseXmlStreamFromBytes(stream, {
  onText(t) { text += t; },
});

assertEquals(text, "Hello");
```

