```ts
import { parse } from "@ende/xml/parse";
import { assertEquals } from "@ende/assert";

const doc = parse(`<root id="1"><child/></root>`);
assertEquals(doc.root.name.local, "root");
assertEquals(doc.root.attributes["id"], "1");
```

Parse items from an XML feed into typed records
```ts
import { parseXmlRecords } from "@ende/xml/parse-records";
import { assertEquals } from "@ende/assert";

type Item = { id: string; title: string };

const xml =
  `<feed><item id="1" title="First"/><item id="2" title="Second"/></feed>`;

const items: Item[] = [];
for await (
  const item of parseXmlRecords<Item>(
    ReadableStream.from([xml]),
    (emit) => ({
      onStartElement(name, _colonIndex, _uri, attributes) {
        if (name !== "item") return;
        let id = "";
        let title = "";
        for (let i = 0; i < attributes.count; i++) {
          const attrName = attributes.getName(i);
          if (attrName === "id") id = attributes.getValue(i);
          else if (attrName === "title") title = attributes.getValue(i);
        }
        emit({ id, title });
      },
    }),
  )
) {
  items.push(item);
}

assertEquals(items, [
  { id: "1", title: "First" },
  { id: "2", title: "Second" },
]);
```

Parse items from a byte stream
```ts
import { parseXmlRecordsFromBytes } from "@ende/xml/parse-records";
import { assertEquals } from "@ende/assert";

const xml = new TextEncoder().encode(
  `<feed><item>First</item><item>Second</item></feed>`,
);

const titles: string[] = [];
for await (
  const title of parseXmlRecordsFromBytes<string>(
    ReadableStream.from([xml]),
    (emit) => {
      let inside = false;
      let text = "";
      return {
        onStartElement(name) {
          if (name === "item") {
            inside = true;
            text = "";
          }
        },
        onText(t) {
          if (inside) text += t;
        },
        onEndElement(name) {
          if (name === "item") {
            emit(text);
            inside = false;
          }
        },
      };
    },
  )
) {
  titles.push(title);
}

assertEquals(titles, ["First", "Second"]);
```

